// Assumed: the admin label and the button both sit on /ops/rules. Adjust the name if the screen differs.
await page.goto('/ops/rules');
// The button's text is a span whose class the button rule should style. The bug drops its type size.
const button = page.getByRole('button').first();
await expect(button).toBeVisible();
const buttonText = button.locator('span').first();
await expect(buttonText).toBeVisible();
// Symptom: the span inside a styled button keeps the button's font size, not the inherited 14px.
await expect(buttonText).toHaveCSS('font-size', '14px');
// Admin label check: the first label-like span on the page should carry the same size.
const label = page.getByText('Admin', { exact: true }).first();
await expect(label).toHaveCSS('font-size', '14px');
